def sumOfUnique(nums):
    # Create a frequency array to count occurrences of each number
    freq = [0] * 101  # Since 1 ≤ nums[i] ≤ 100
    for num in nums:
        freq[num] += 1

    # Sum up numbers that appear exactly once
    total = 0
    for num in nums:
        if freq[num] == 1:
            total += num
    return total
